from itertools import permutations
people = ['Alice','Bob','Charlie','David','Ethan','Frankie']

def norm_pair(a,b):
    return tuple(sorted([a,b]))

def adj(pos, a, b):
    return (pos[a]-pos[b])%6 in (1,5)

def two_left(pos, guest, ref):
    return pos[guest] == (pos[ref]-2)%6

def two_right(pos, guest, ref):
    return pos[guest] == (pos[ref]+2)%6

def across(pos, a, b):
    return (pos[a]-pos[b])%6 == 3

pairs=set()
valid=[]
# fix Alice at 0 to quotient rotations
for rest in permutations([p for p in people if p!='Alice']):
    seating=('Alice',)+rest
    pos={p:i for i,p in enumerate(seating)}
    if not two_left(pos,'Bob','Alice'):
        continue
    if adj(pos,'Bob','Ethan'):
        continue
    if adj(pos,'Alice','Frankie'):
        continue
    if not (adj(pos,'Frankie','David') or adj(pos,'Frankie','Ethan')):
        continue
    if across(pos,'Ethan','Bob') and not two_right(pos,'David','Alice'):
        continue
    valid.append(seating)
    i=pos['Charlie']
    pairs.add(norm_pair(seating[(i-1)%6], seating[(i+1)%6]))
print('valid', len(valid))
for s in valid:
    print(s, 'Charlie between', norm_pair(s[(s.index('Charlie')-1)%6], s[(s.index('Charlie')+1)%6]))
print('pairs')
for p in sorted(pairs): print(', '.join(p))
